    "text": "융합전공은 여러 학과가 함께 여는 독립 전공과정이에요. 2학년 이상·35학점(2016학년도 이후 입학생은 33학점) 이상이면 1월·7월에 클래스넷으로 신청하고, 융합전공 교과목을 36학점 이상 들어야 해요.",
