    "text": "수강철회는 정정기간이 끝난 뒤 2~3일, 그리고 개강 후 3~4주차 중 2일(추가 수강철회)에 클래스넷 › 수강신청 › 정규학기 수강신청 › 「수강신청 철회하기」에서 해요. 신청학점이 15학점 밑이면 다음 학기 교내장학금, 12학점 밑이면 국가장학금 자격에 못 미칠 수 있어요.",
