       "구분: 최대 이수 가능 학점 · 2022학년도 신입생부터(2022~): 교양+전공+OCU(일반선택) · 2016학년도 신입생부터 2021학년도 신입생까지(2016~2021): 교양+전공+OCU(일반선택) · 2015학년도 신입생까지(~2015): 교양+전공+OCU(일반선택)",
