    "text": "사이버강좌는 학기당 최대 2과목(외국인 학생은 1과목)까지 듣고, 졸업까지 2022학번부터 누적 24학점, 2016~2021학번 26학점, 2015학번까지 28학점까지예요. 주차별 강의를 출석 인정기간 안에 90% 이상 봐야 출석으로 인정돼요.",
