       "비어문계열의 영어전용강좌 (2007학년도 2학기부터 시행)",
       "① 영어전용강좌(영어관련 전공 및 교양과목, 원어민 강좌 제외)를 수강하면, 성적증명 발급시 추가로 \\'전공영어\\' 1학점(일반선택, P/F)을 부여한다. 다만, 영어를 모국어로 사용하는 외국인 학생에 대해서는 추가 1학점을 부여하지 않는다.",
       "② 추가로 인정하는 1학점은 이수학점 한계에 포함하지 않으며, 재학 중 최대 5학점까지 취득할 수 있다. (추가 1학점의 이수구분은\\'일반선택\\'임)",
       "③ 재수강 및 교과목 폐지로 인한 학점 포기시, 기 취득한 추가 1학점은 그대로 유지되며, 해당 과목의 본래 학점만 취득 또는 삭제된다.",
       "④ 영어전용강좌에 대해서는 상대평가를 적용하지 않으며 기타 세부사항은 별도로 정한다.",
       "* 영어전용강좌에 대한 미졸업자 및 계절학기 수강생의 등록금 납부액은 해당과목의 본래 학점(추가 1학점 무관)에 따름",
