       "A) 학생이 입학했을 때부터 지금까지 취득한 전공(또는 교양) 영어과목이 누적 몇과목인가요? 이번 학기까지 포함하여 누적 6개 과목이라면 5개 과목까지만 1학점이 추가되는 것입니다. 6번째 과목부터는 추가로 1학점이 부여되지 않습니다.",
       "자주 하는 질문 - 2",
