       "A) 영어전용강좌에 대해 추가 1학점은 성적정정기간까지 모두 끝나고 증명서 발급이 시작되는 날부터 클래스넷 \\'전체성적조회\\'에서 확인이 가능합니다. (단, 누적 전공영어 과목수가 5개까지에 한해서만 추가 1학점이 있습니다)",
