    "text": "교내장학금 대부분(7종)은 따로 신청하지 않아요. 매 학기 한국장학재단 국가장학금 1차 신청을 하면 자동으로 신청되고, 성적이 나온 뒤 학과가 선발해요. 1학기 장학금은 11~12월경, 2학기 장학금은 5~6월경에 신청해요.",
