       "성격: 정진 · 장학금명: 90만원 · 장학금액: 3.0",
       "성격: 가계 지원 (2종) · 장학금명: 한마음 · 장학금액: 50% · 최소 취득학점: 성적경고 아니면 가능",
       "성격: 면학 · 장학금명: 120만원",
       "1. 본교의 교내장학금은 매학기 성적을 기준으로 학과에서 경쟁을 통해 선발하는 교내장학금 7종(성적우수 5종,가계지원 2종)을 비롯하여 입학시부터 자격을 부여받는 계속지급 장학금(입학성적우수,보훈 등), 별도의 신청과 활동을 통해 수혜 받는 봉사장학금, 신용카드수수료장학금, 공로장학금 등으로 구성되어 있음",
